import os, re, sys

root = "."

# ---------- helpers ----------
def read_file(p):
    try:
        with open(p, 'r', errors='replace') as f:
            return f.read()
    except Exception:
        return None

FUNC_DEF = re.compile(r'^[A-Za-z_][A-Za-z0-9_ \t\*]*?\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(', re.M)

def extract_functions(text):
    """Return dict fn_name -> (start_line, body). Uses brace matching from the line where the definition's opening brace appears."""
    funcs = {}
    lines = text.split('\n')
    n = len(lines)
    i = 0
    # match: [storage] [return type] name(args)  possibly multiline, then '{'
    fdef = re.compile(r'^([A-Za-z_][A-Za-z0-9_ \t\*]*?)\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(')
    while i < n:
        line = lines[i]
        m = fdef.match(line)
        if m and m.group(2) not in ('if','for','while','switch','return','sizeof','defined'):
            # find opening brace within next ~15 lines, allowing args continuation
            j = i
            depth_paren = 0
            found_open = -1
            while j < min(i+25, n):
                depth_paren += lines[j].count('(') - lines[j].count(')')
                if depth_paren == 0 and j >= i:
                    # after closing paren, look for '{'
                    k = j
                    while k < min(j+4, n):
                        if '{' in lines[k]:
                            found_open = k
                            break
                        if ';' in lines[k]:
                            break
                        k += 1
                    if found_open >= 0:
                        break
                    break
                j += 1
            if found_open >= 0:
                # brace matching
                depth = 0
                k = found_open
                start_body = found_open
                while k < n:
                    depth += lines[k].count('{') - lines[k].count('}')
                    if depth == 0 and k >= start_body:
                        body = '\n'.join(lines[start_body:k+1])
                        funcs[m.group(2)] = (i+1, body, start_body+1, k+1)
                        i = k
                        break
                    k += 1
        i += 1
    return funcs

PAT_PLAIN_LOCK = re.compile(r'(?<![\w_])spin_lock\s*\(&?([A-Za-z0-9_\>\.\-\[\]arious]+)\s*\)')
PAT_PLAIN = re.compile(r'(?<![\w_])spin_lock\s*\(([^)]+)\)')
PAT_BH = re.compile(r'spin_lock_bh\s*\(([^)]+)\)')
PAT_IRQSAVE = re.compile(r'spin_lock_irq(?:save)?\s*\(([^,)]+)')

def lock_names_in(body):
    """plain spin_lock lock expressions"""
    out = []
    for m in PAT_PLAIN.finditer(body):
        arg = m.group(1).strip()
        out.append(arg)
    return out

def all_lock_variants(body):
    res = {'plain': [], 'bh': [], 'irqsave': [], 'irq': []}
    for m in re.finditer(r'spin_lock_bh\s*\(([^)]+)\)', body):
        res['bh'].append(m.group(1).strip())
    for m in re.finditer(r'spin_lock_irqsave\s*\(([^,)]+)', body):
        res['irqsave'].append(m.group(1).strip())
    for m in re.finditer(r'spin_lock_irq\s*\(([^)]+)\)', body):
        res['irq'].append(m.group(1).strip())
    for m in re.finditer(r'spin_lock\s*\(([^)]+)\)', body):
        res['plain'].append(m.group(1).strip())
    return res

def normalize(lockexpr):
    return re.sub(r'\s+', '', lockexpr)

# ---------- pass 1: identify NAPI poll fns and tasklet cbs per file ----------
report = []

for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d not in ('.git',)]
    for fn in filenames:
        if not fn.endswith('.c'):
            continue
        p = os.path.join(dirpath, fn)
        text = read_file(p)
        if text is None:
            continue
        if 'netif_napi_add' not in text and 'tasklet' not in text:
            continue
        funcs = extract_functions(text)
        softirq_fns = {}  # fn -> reason
        # NAPI poll: 3rd arg of netif_napi_add(dev, &n, fn, weight)
        for m in re.finditer(r'netif_napi_add(?:_weight|_ex)?\s*\(([^;]*?)\)', text, re.S):
            args = m.group(1)
            parts = [a.strip() for a in args.split(',')]
            if len(parts) >= 3:
                cand = parts[2].strip()
                cand = re.sub(r'^&?', '', cand)
                if re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', cand):
                    softirq_fns[cand] = ('NAPI', text.count('\n',0,m.start())+1)
        # tasklet callbacks
        for m in re.finditer(r'tasklet_init\s*\(\s*[^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)\s*,', text):
            softirq_fns[m.group(1)] = ('TASKLET', text.count('\n',0,m.start())+1)
        for m in re.finditer(r'tasklet_setup\s*\(\s*[^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)', text):
            softirq_fns[m.group(1)] = ('TASKLET', text.count('\n',0,m.start())+1)
        for m in re.finditer(r'DECLARE_TASKLET\s*\(\s*\w+\s*,\s*([A-Za-z_][A-Za-z0-9_]*)\s*,', text):
            softirq_fns[m.group(1)] = ('TASKLET', text.count('\n',0,m.start())+1)
        for m in re.finditer(r'DECLARE_TASKLET_OLD\s*\(\s*\w+\s*,\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)', text):
            softirq_fns[m.group(1)] = ('TASKLET', text.count('\n',0,m.start())+1)
        # struct tasklet_struct x = { .func = fn }
        for m in re.finditer(r'\.func\s*=\s*([A-Za-z_][A-Za-z0-9_]*)', text):
            softirq_fns[m.group(1)] = ('TASKLET?', text.count('\n',0,m.start())+1)
        if not softirq_fns:
            continue
        # only keep ones whose definition exists in this file
        softirq_fns = {k:v for k,v in softirq_fns.items() if k in funcs}
        if not softirq_fns:
            continue

