        callees = {}
        for fname, (defline, body, bl, el) in funcs.items():
            calls = set(re.findall(r'(?<![\w\.>])([a-zA-Z_][a-zA-Z0-9_]*)\s*\(', body))
            calls.discard(fname)
            callees[fname] = {c for c in calls if c in funcs}

        def transitive(fn):
            seen = set()
            stack = [fn]
            while stack:
                cur = stack.pop()
                if cur in seen: continue
                seen.add(cur)
                stack.extend(callees.get(cur, ()))
            return seen

